(()=>{
  const images = ["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"];
  const slots = [0, 2, 6, 8, 7, 9];
  const alt = ["Nad Zainal in a floral white hijab portrait", "Nad Zainal in a taupe hijab and grey blazer", "Nad Zainal in a soft pink hijab portrait", "Nad Zainal in a white hijab lifestyle selfie", "Nad Zainal in a bright pink embroidered hijab look", "Nad Zainal in an elegant light grey hijab portrait"];
  const apply = () => {
    const gallery = document.querySelectorAll('.social-mosaic img');
    slots.forEach((slot, i) => {
      const image = gallery[slot];
      if (!image) return;
      image.src = images[i];
      image.alt = alt[i];
      image.removeAttribute('referrerpolicy');
    });
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply, { once: true });
  else apply();
})();
